/*
 * humidity-tile-buttons.js
 *
 * Gives humidifier tiles the same inline minus/plus widget that climate tiles get for temperature.
 *
 * Home Assistant's built-in Climate, Home and Areas pages are generated by view strategies, and
 * every tile's feature is chosen by computeAreaTileCardConfig from a fixed chain:
 *
 *     light-brightness -> cover-open-close -> target-temperature -> fan-speed -> alarm-modes
 *     -> lock-commands
 *
 * `target-humidity` is not in that chain, and it renders a slider rather than buttons anyway, so a
 * humidifier tile on those pages carries no control at all. Nothing an integration reports can
 * change that decision, because it is taken in the frontend.
 *
 * This module does two things:
 *
 *   1. registers a custom card feature, `custom:humidity-number-buttons`, that renders the same
 *      <ha-control-number-buttons> the temperature feature uses, with the unit set to % and the
 *      bounds read from the entity, calling humidifier.set_humidity;
 *   2. wraps the built-in view strategies so humidifier tiles they generate carry that feature.
 *      getLovelaceStrategy resolves a built-in strategy with customElements.get(tag) on every
 *      regeneration and then calls its static generate(), so wrapping that method is enough and
 *      keeps working for the life of the page.
 *
 * It only ever ADDS a feature to a tile that has none. Every hook is wrapped so that a failure
 * degrades to stock Home Assistant rather than a broken dashboard.
 */

const FEATURE_TYPE = "humidity-number-buttons";
const TAG = "humidity-number-buttons-feature";
const LOG = "[humidity-tile-buttons]";

// Built-in view strategies whose tiles should get the feature. Tag names are
// `${strategyType}-${configType}-strategy`, per getStrategyTag().
const STRATEGY_TAGS = [
  "climate-view-strategy",
  "home-area-view-strategy",
  "area-view-strategy",
  "home-overview-view-strategy",
  "areas-overview-view-strategy",
];

const isHumidifier = (entityId) =>
  typeof entityId === "string" && entityId.startsWith("humidifier.");

class HumidityNumberButtonsFeature extends HTMLElement {
  static getStubConfig() {
    return { type: `custom:${FEATURE_TYPE}` };
  }

  setConfig(config) {
    if (!config) throw new Error("Invalid configuration");
    this._config = config;
  }

  set hass(hass) {
    this._hass = hass;
    this._render();
  }

  // Modern Home Assistant passes `context`; older builds passed `stateObj`.
  set context(context) {
    this._context = context;
    this._render();
  }

  set stateObj(stateObj) {
    this._stateObj = stateObj;
    this._render();
  }

  get _entityId() {
    return this._context?.entity_id || this._stateObj?.entity_id;
  }

  get _state() {
    const id = this._entityId;
    return id && this._hass ? this._hass.states[id] : undefined;
  }

  _setValue(value) {
    const stateObj = this._state;
    if (!stateObj || typeof value !== "number" || Number.isNaN(value)) return;
    this._hass.callService("humidifier", "set_humidity", {
      entity_id: stateObj.entity_id,
      humidity: value,
    });
  }

  _render() {
    const stateObj = this._state;
    if (!this._hass || !stateObj || !isHumidifier(stateObj.entity_id)) {
      this.innerHTML = "";
      return;
    }

    const attrs = stateObj.attributes || {};
    const value = attrs.humidity;
    const min = attrs.min_humidity ?? 0;
    const max = attrs.max_humidity ?? 100;
    const step = attrs.target_humidity_step ?? 1;
    const disabled = stateObj.state === "unavailable";

    // <ha-control-number-buttons> is the element the temperature feature uses. It is bundled with
    // the frontend but only defined once something has imported it, which a climate tile on the
    // same page does. Fall back to a plain row when it is not there, so the control still works.
    if (customElements.get("ha-control-number-buttons")) {
      let el = this._widget;
      if (!el || el.tagName.toLowerCase() !== "ha-control-number-buttons") {
        this.innerHTML = "";
        el = document.createElement("ha-control-number-buttons");
        el.addEventListener("value-changed", (ev) =>
          this._setValue(ev.detail?.value)
        );
        this.appendChild(el);
        this._widget = el;
      }
      el.value = value;
      el.min = min;
      el.max = max;
      el.step = step;
      el.unit = "%";
      el.disabled = disabled;
      el.locale = this._hass.locale;
      el.label = "Humidity";
      return;
    }

    this._renderFallback(value, min, max, step, disabled);
  }

  _renderFallback(value, min, max, step, disabled) {
    if (!this._fallback) {
      this.innerHTML =
        '<div class="hnb-row">' +
        '<button class="hnb-btn" data-dir="-1">&minus;</button>' +
        '<span class="hnb-value"></span>' +
        '<button class="hnb-btn" data-dir="1">+</button>' +
        "</div>" +
        "<style>" +
        ".hnb-row{display:flex;align-items:center;justify-content:space-between;" +
        "background:var(--control-button-background-color,rgba(var(--rgb-disabled-color,110,110,110),.2));" +
        "border-radius:var(--control-button-border-radius,12px);height:42px;padding:0 4px;}" +
        ".hnb-btn{flex:0 0 auto;width:40px;height:38px;border:none;background:none;cursor:pointer;" +
        "color:var(--primary-text-color);font-size:20px;line-height:1;}" +
        ".hnb-btn[disabled]{opacity:.4;cursor:default;}" +
        ".hnb-value{flex:1 1 auto;text-align:center;color:var(--primary-text-color);font-size:14px;}" +
        "</style>";
      this._fallback = true;
      this.querySelectorAll(".hnb-btn").forEach((btn) => {
        btn.addEventListener("click", () => {
          const dir = Number(btn.dataset.dir);
          const cur = this._state?.attributes?.humidity;
          if (typeof cur !== "number") return;
          const next = Math.min(
            this._state.attributes.max_humidity ?? 100,
            Math.max(
              this._state.attributes.min_humidity ?? 0,
              cur + dir * (this._state.attributes.target_humidity_step ?? 1)
            )
          );
          this._setValue(next);
        });
      });
    }
    const label = this.querySelector(".hnb-value");
    if (label) label.textContent = value == null ? "--" : `${value} %`;
    this.querySelectorAll(".hnb-btn").forEach((btn) => {
      btn.disabled = disabled;
    });
  }
}

if (!customElements.get(TAG)) {
  customElements.define(TAG, HumidityNumberButtonsFeature);
}

window.customCardFeatures = window.customCardFeatures || [];
if (!window.customCardFeatures.some((f) => f.type === FEATURE_TYPE)) {
  window.customCardFeatures.push({
    type: FEATURE_TYPE,
    name: "Humidity buttons",
    supported: (stateObj) => isHumidifier(stateObj?.entity_id),
    configurable: false,
  });
}

// Walk a generated view and attach the feature to every featureless humidifier tile.
const decorate = (node) => {
  if (!node || typeof node !== "object") return;
  if (Array.isArray(node)) {
    node.forEach(decorate);
    return;
  }
  if (
    node.type === "tile" &&
    isHumidifier(node.entity) &&
    (!node.features || node.features.length === 0)
  ) {
    node.features = [{ type: `custom:${FEATURE_TYPE}` }];
    node.features_position = node.features_position || "bottom";
  }
  if (node.sections) decorate(node.sections);
  if (node.cards) decorate(node.cards);
  if (node.views) decorate(node.views);
};

const patchStrategy = (tag) => {
  customElements
    .whenDefined(tag)
    .then(() => {
      const cls = customElements.get(tag);
      if (!cls || typeof cls.generate !== "function" || cls.__humidityPatched) {
        return;
      }
      const original = cls.generate.bind(cls);
      cls.generate = async function generate(config, hass) {
        const result = await original(config, hass);
        try {
          decorate(result);
        } catch (err) {
          console.error(LOG, "could not decorate", tag, err);
        }
        return result;
      };
      cls.__humidityPatched = true;
    })
    .catch((err) => console.error(LOG, "could not patch", tag, err));
};

try {
  STRATEGY_TAGS.forEach(patchStrategy);
  console.info(
    LOG,
    `registered custom:${FEATURE_TYPE} and armed ${STRATEGY_TAGS.length} strategies`
  );
} catch (err) {
  console.error(LOG, "setup failed", err);
}
